def split_csv(line):
    n = len(line)
    if n == 0:
        return [""]

    fields = []
    i = 0

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            buf = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(c)
                    i += 1
            if not closed:
                return None
            # after closing quote must be comma or end
            if i < n:
                if line[i] == ',':
                    i += 1
                else:
                    return None
            fields.append(''.join(buf))
        else:
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                i += 1
            fields.append(line[start:i])
            if i < n:
                i += 1  # skip comma
            else:
                break
            if i >= n:
                # trailing comma -> empty field after
                fields.append("")
                break
            continue

        if i >= n:
            break

    return fields

